∀ {F : Type} {before after : GoldbachDirect.State F} {parameters : List (GoldbachDirect.CType × String)}
  {values : List GoldbachDirect.Value},
  GoldbachDirect.Semantics.bindParameters before parameters values = Option.some after → after.foreign = before.foreign

∀ {F : Type} {context : GoldbachDirect.Semantics.Context F} {before after : GoldbachDirect.State F}
  {literal : GoldbachDirect.Literal} {expected : GoldbachDirect.Value} {expression : GoldbachDirect.Expr}
  {values : List GoldbachDirect.Value},
  literal.value = Option.some expected →
    GoldbachDirect.Semantics.Args context before [GoldbachDirect.Expr.literal literal, expression] values after →
      ∃ value, values = [expected, value] ∧ GoldbachDirect.Semantics.Eval context before expression value after
